const dacman2BaseFile = (path) => dacman2ProjectFiles.find((file) => file.path === path);
export const dacman2RevisionBProjectFiles = dacman2ProjectFiles.map((file) => {
  const levelMatch = /^dacman2-level(\d+)\.name\.zx0$/.exec(file.path);
  if (!levelMatch) return file;
  const level = Number(levelMatch[1]);
  if (level === 7) return { ...file, base64: dacman2BaseFile("dacman2-level5.name.zx0").base64 };
  return dacman2RevisionBLevelBase64[level] ? { ...file, base64: dacman2RevisionBLevelBase64[level] } : file;
});
